n = 2
for fname, title, intro, items in CH:
    md = [f"# {title}", "", intro, ""]
    for t, quand, txt in items:
        md += [f"## {n}. {t}", "", f"*À utiliser {quand}*", "", "::: {.prompt}", f"Prompt {n}", "", txt, ":::", ""]
        n += 1
    open(os.path.join(H, "manuscrit", f"{fname}.md"), "w", encoding="utf-8").write("\n".join(md))
print("prompts générés jusqu'au n°", n - 1)
